<div class="form-field"><label for="task-title">Task name</label><input id="task-title" name="title" value="{{ old('title', $task?->title) }}" placeholder="e.g. Plan the week" required maxlength="120"></div>
<div class="form-field"><label for="task-description">Details <span>(optional)</span></label><textarea id="task-description" name="description" rows="3" placeholder="Add a little context...">{{ old('description', $task?->description) }}</textarea></div>
<div class="form-columns"><div class="form-field"><label for="task-due-date">Due date <span>(optional)</span></label><input id="task-due-date" type="date" name="due_date" value="{{ old('due_date', $task?->due_date?->format('Y-m-d')) }}"></div><div class="form-field"><label for="task-status">Status</label><select id="task-status" name="status"><option value="pending" @selected(old('status', $task?->status ?? 'pending') === 'pending')>Pending</option><option value="completed" @selected(old('status', $task?->status) === 'completed')>Completed</option></select></div></div>